<script setup>
import {ref} from 'vue'
import {positions,positionCN,sources} from '../data/system'
import {position,source,keywords,keywordPool,toggleKeyword,reset,archive} from '../composables/useArchive'
const allKeywords=ref(false),sourceOpen=ref(false)
const count=p=>archive.filter(o=>o.curatorialPosition===p).length
</script>
<template><div class="filter-panel"><header class="brand"><span class="mono">R / OS — 02</span><h1>RESERVOIR<span>蓄水池</span></h1><p>OPERATING SYSTEM<br>策展研究系统</p></header><div class="sidebar-label"><span>POSITION / 策展位置</span><button @click="reset">重置 ↺</button></div><nav class="position-options" aria-label="策展位置"><button :class="{selected:!position}" @click="position=''"><span>ALL / 全部档案</span><b>{{archive.length}}</b></button><button v-for="(p,i) in positions" :key="p" :class="{selected:position===p}" @click="position=position===p?'':p"><span><small>{{'ABCDEF'[i]}} {{p}}</small><strong>{{positionCN[i]}}</strong></span><b>{{count(p)}}</b></button></nav><section class="source-section"><button class="sidebar-label" @click="sourceOpen=!sourceOpen" :aria-expanded="sourceOpen">SOURCE / 来源类型 <span>{{sourceOpen?'−':'+'}}</span></button><div class="source-options" v-if="sourceOpen"><button @click="source=''" :class="{selected:!source}">全部 / ALL</button><button v-for="(s,i) in [...sources,'UNCLASSIFIED']" :key="s" @click="source=source===s?'':s" :class="{selected:source===s}">{{['基础设施','建筑','艺术','文学','日常','身体','语言与观念','景观','未标注'][i]}} / {{s}}</button></div></section><section class="dredge"><div class="sidebar-label">DREDGE / 打捞</div><p>从一个词，进入另一种关系。<small>FOLLOW A WORD INTO THE ARCHIVE.</small></p><div class="keyword-pool"><button v-for="k in (allKeywords?keywordPool:keywordPool.slice(0,28))" :key="k" @click="toggleKeyword(k)" :class="{selected:keywords.includes(k)}" :aria-pressed="keywords.includes(k)">{{k}}</button></div><button class="text-link" @click="allKeywords=!allKeywords">{{allKeywords?'收起 / LESS −':`全部关键词 / ALL ${keywordPool.length} +`}}</button></section></div></template>
